pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 fuzz_unlockTime, uint256 fuzz_amount) public {
        // Admissible domain: amount > 0 so that Put actually deposits, unlockTime can be any uint256
        vm.assume(fuzz_amount > 0);
        address alice = address(0x1000);
        vm.deal(alice, fuzz_amount);
        vm.prank(alice);
        c.Put{value: fuzz_amount}(fuzz_unlockTime);
        (uint storedUnlockTime, uint storedBalance) = c.Acc(alice);
