pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlockTime, uint128 depositAmount) public {
        // Restrict depositAmount to a non-zero value to ensure a state change occurs
        vm.assume(depositAmount > 0);
        // Restrict unlockTime to a reasonable range to avoid overflow in comparisons
        unlockTime = bound(unlockTime, 1, type(uint64).max);

        address caller = address(0xBEEF);
        vm.deal(caller, depositAmount);

        // Warp to a known timestamp before the call to allow a clear before/after comparison
        uint256 callTimestamp = block.timestamp + 1 days;
        vm.warp(callTimestamp);

        vm.prank(caller);
        c.Put{value: depositAmount}(unlockTime);

        // After Put, the caller's unlockTime must be >= the block.timestamp at the time of the call.
        // The reference contract ensures this; the mutant leaves it possibly 0 (default),
        // which will be strictly less than callTimestamp.
        (, uint256 storedUnlockTime) = c.Acc(caller);
        assertTrue(storedUnlockTime >= callTimestamp);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint128 _amount) public {
        // Ensure Put amount is at least MinSum and non-zero to allow Collect
        uint amount = bound(_amount, 1 ether, type(uint128).max);
        address sender = address(0x1234);
        vm.deal(sender, amount * 2);

        // First Put with provided _unlockTime
        vm.prank(sender);
        c.Put{value: amount}(_unlockTime);

        // Warp to after both the original unlockTime and block.timestamp of first call
        // but only if _unlockTime was in the past; we want to test Collect after block.timestamp
        uint warpTime = block.timestamp + 1;
        if (_unlockTime > block.timestamp) {
            warpTime = _unlockTime + 1;
        }
        vm.warp(warpTime);

        // Second Put with no value just to set balance (not needed, balance already set)
        // Now Collect with the amount
        vm.prank(sender);
        bool ok;
        try c.Collect(amount) { ok = true; } catch { ok = false; }

        // In reference, unlockTime was set to max(_unlockTime, block.timestamp), so Collect should succeed after warpTime
        // In mutant, unlockTime is 0 (default), so block.timestamp > 0 always, Collect should also succeed if balance >= amount
        // Wait, the mutant's unlockTime is 0, and block.timestamp after warp is > 0, so Collect should succeed in both...
        // We need a case where the reference sets unlockTime to a high value that prevents Collect, but the mutant's 0 allows it.
        // Let's make the reference set unlockTime to a future time, warp to before that, and try Collect: reference fails, mutant succeeds (since unlockTime=0 < block.timestamp).
        // So: set _unlockTime in the future, warp to before it, then Collect.
        vm.warp(1000); // reset to a known base
        vm.prank(sender);
        // Send ether via fallback? No, use Put.
        c.Put{value: amount}(block.timestamp + 1000); // future unlockTime
        vm.warp(block.timestamp + 500); // in between
        vm.prank(sender);
        try c.Collect(amount) returns (bool) { ok = true; } catch { ok = false; }
        assertTrue(ok == false); // reference should revert, mutant should not revert
    }
}

