pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 _unlockTime, uint256 putAmount, uint256 collectAmount, address actor) public {
        // Bound amounts to admissible range
        vm.assume(actor != address(0) && actor != address(this));
        putAmount = bound(putAmount, 1 ether, 1000 ether);
        collectAmount = bound(collectAmount, 0, putAmount);
        _unlockTime = bound(_unlockTime, 0, block.timestamp + 365 days);

        // Fund actor and call Put
        vm.deal(actor, putAmount);
        vm.prank(actor);
        c.Put{value: putAmount}(_unlockTime);

        // Warp to a time strictly after block.timestamp but possibly before the intended unlockTime
        // This ensures reference unlockTime >= previous block.timestamp, while mutant unlockTime could be 0
        uint256 warpTime = block.timestamp + 1;
        vm.warp(warpTime);

        // The rule: if the current timestamp <= the reference's unlockTime (which is >= the original block.timestamp),
        // Collect should revert (since unlockTime won't be met). But the mutant may have unlockTime=0, allowing Collect.
        // We assert that Collect reverts when warpTime < max(_unlockTime, originalTimestamp)
        uint256 originalTimestamp = block.timestamp - 1; // block.timestamp after Put
        uint256 expectedUnlock = _unlockTime > originalTimestamp ? _unlockTime : originalTimestamp;
        bool expectedRevert = warpTime < expectedUnlock;

        vm.prank(actor);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Assert: Collect reverts exactly when the reference says it should (i.e., before unlockTime)
        // The buggy version might not revert when expectedRevert is true because its unlockTime is 0.
        assertTrue(success != expectedRevert);
    }
}

