        // Keep msgValue reasonable to avoid overflow
        vm.assume(msgValue <= type(uint256).max / 2);
        // Ensure sender isn't a precompile or the contract itself to avoid revert on low-level call in Collect
        vm.assume(sender != address(0) && sender != address(c) && sender != address(this));
        vm.deal(sender, msgValue);
        vm.startPrank(sender);
        c.Put{value: msgValue}(_unlockTime);
        vm.stopPrank();
        // After Put, the stored unlockTime must be >= the supplied parameter
