import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 unlockTime, uint256 collectAmount) public {
        // Admissible domain: amounts > 0, unlockTime can be any value, collectAmount <= amounts
        vm.assume(amount1 > 0);
        vm.assume(amount2 > 0);
        // Ensure the amounts are not too large to avoid overflow in balance additions for the test wallet
        vm.assume(amount1 <= 1 ether * 1e12);
        vm.assume(amount2 <= 1 ether * 1e12);
        // Unlock time must be strictly greater than block.timestamp to test the property
        vm.assume(unlockTime > block.timestamp);
        // Collect amount must be at most the total balance of the account
        vm.assume(collectAmount <= amount1 + amount2);

        // Deploy a helper attacker that re-enters during Collect.
        // The property concerns the invariant that if unlockTime > block.timestamp, no collects should succeed,
        // therefore the contract balance must remain >= the sum of all deposits made with future unlockTime.
        // The bug makes unlockTime = block.timestamp, which is <= block.timestamp, allowing premature collect.
        // We need to test the case where unlockTime is set to a future time, but the bug sets it to now,
        // allowing immediate withdrawal.
        // To show the property violation, we must have a call to Collect from a sender that has a balance
        // and an unlockTime set by a bug-induced Put. The invariant is that while unlockTime > block.timestamp,
        // the sum of balances of all such holders is backed by the contract's balance.
        // Because the contract sends ETH via call, the sender address must be a contract that can receive ETH.
        // We use a helper that simply accepts ETH.

        // We simulate two different actors depositing with future unlockTime, then check invariant after bug would set unlockTime to now.
    }
}

