pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint256 _val, uint256 _collectAmt) public {
        // Restrict inputs to admissible domain
        vm.assume(_val > 0);
        vm.assume(_collectAmt > 0);
        address actor = address(0x1337);
        vm.assume(actor != address(c));
        vm.deal(actor, _val);

        // Put funds
        vm.prank(actor);
        c.Put{value: _val}(_unlockTime);

        // Warp to after current timestamp
        uint256 warpTime = block.timestamp + 1;
        vm.warp(warpTime);

        // Ensure enough balance for Collect
        if (c.Acc(actor).balance < _collectAmt || c.Acc(actor).balance < c.MinSum()) {
            return;
        }

        // Record balance before Collect
        uint256 balanceBefore = c.Acc(actor).balance;
        vm.prank(actor);
        bool ok = false;
        try c.Collect(_collectAmt) { ok = true; } catch {}

        // If Collect succeeded, unlockTime must be > block.timestamp
        // In buggy version, unlockTime == 0, so Collect succeeds even though block.timestamp > 0
        // In correct version, unlockTime is max(_unlockTime, block.timestamp), so it can only succeed if unlockTime < block.timestamp
        if (ok) {
            // Funds were withdrawn; this should only happen if unlockTime was set properly
            // Correct: acc.unlockTime >= block.timestamp at time of Put, so unlockTime <= block.timestamp when Collect called
            // Buggy: unlockTime=0, so always succeeds after warp
            // Rule: if Collect succeeds, then unlockTime must be > 0
            assertTrue(c.Acc(actor).unlockTime > 0);
        }
    }
}

