pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 unlockTime, uint256 collectAmt) public {
        // Bound amounts to reasonable ranges to avoid overflow and stay within testable limits
        amount1 = bound(amount1, 0, 1000 ether);
        amount2 = bound(amount2, 0, 1000 ether);
        unlockTime = bound(unlockTime, 0, type(uint256).max);
        collectAmt = bound(collectAmt, 0, amount1 + amount2);

        // Use two distinct actors to test the invariant across accounts
        address alice = address(0x1);
        address bob = address(0x2);

        // Record initial contract balance (should be 0)
        uint256 initialBalance = address(c).balance;

        // Alice puts ether
        vm.deal(alice, amount1);
        vm.prank(alice);
        c.Put{value: amount1}(unlockTime);

        // Bob puts ether
        vm.deal(bob, amount2);
        vm.prank(bob);
        c.Put{value: amount2}(unlockTime);

        // Warp past unlockTime to allow collection
        vm.warp(block.timestamp + unlockTime + 1);

        // Alice tries to collect, but collectAmt should not exceed her balance
        // We ensure collectAmt doesn't exceed Alice's balance in the correct version
        uint256 aliceBalance = c.Acc(alice).balance;
        uint256 amt = collectAmt > aliceBalance ? aliceBalance : collectAmt;
        if (amt > 0) {
            vm.prank(alice);
            c.Collect(amt);
        }

        // Calculate total ether received = initial contract balance + all msg.value sent
        uint256 totalReceived = initialBalance + amount1 + amount2;
        // Calculate total paid out = address(c).balance difference from total received
        uint256 totalPaidOut = totalReceived - address(c).balance;

        // Sum of all account balances
        uint256 sumBalances = c.Acc(alice).balance + c.Acc(bob).balance;

        // The invariant: sumBalances + totalPaidOut == totalReceived
        // In the correct version, this always holds.
        // In the mutant, Put does not update balance, so msg.value is lost from sumBalances,
        // breaking the invariant.
        assertTrue(sumBalances + totalPaidOut == totalReceived);
    }
}

