pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 unlockTime) public {
        vm.assume(depositAmount > 0 && depositAmount <= 1 ether);
        // Deploy a re-entrant attacker that calls Put during Collect
        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), depositAmount);
        attacker.attack(depositAmount, unlockTime);
        // After attack, total deposits should equal balance
        uint256 balance = c.Acc(address(attacker)).balance;
        assertTrue(balance == depositAmount);
    }
}

contract Attacker {
    C target;
    bool attacking;
    constructor(C _target) { target = _target; }
    receive() external payable {
        if (!attacking) {
            attacking = true;
            target.Put(0);
            attacking = false;
        }
    }
    function attack(uint256 amount, uint256 unlockTime) external payable {
        target.Put{value: amount}(unlockTime);
        target.Collect(amount);
    }
}

