import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTime, uint256 reenterAmount) public {
        amount = bound(amount, 0, 1000 ether);
        reenterAmount = bound(reenterAmount, 0, 1000 ether);
        unlockTime = bound(unlockTime, block.timestamp + 1, block.timestamp + 365 days);
        vm.assume(amount > 0 || reenterAmount > 0);

        ReenteringAttacker attacker = new ReenteringAttacker(c);
        vm.deal(address(attacker), amount + reenterAmount);
        attacker.attack{value: amount}(unlockTime, reenterAmount);

        uint256 attackerAccBalance = c.Acc(address(attacker));
        assertTrue(attackerAccBalance == amount + reenterAmount);
    }
}

contract ReenteringAttacker {
    C public target;
    uint256 private _unlockTime;
    uint256 private _reenterAmount;
    bool private _isReentering;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 unlockTime, uint256 reenterAmount) external payable {
        _unlockTime = unlockTime;
        _reenterAmount = reenterAmount;
        target.Put{value: msg.value}(unlockTime);
    }

    fallback() external payable {
        if (address(this).balance >= _reenterAmount && !_isReentering) {
            _isReentering = true;
            target.Put{value: _reenterAmount}(_unlockTime);
            _isReentering = false;
        }
    }
}

