pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 unlockTime) public {
        vm.assume(depositAmount > 0 && depositAmount < 1e36);
        // Deploy reentrant attacker
        ReenteringAttacker attacker = new ReenteringAttacker(c);
        vm.deal(address(attacker), depositAmount);
        // First, put some funds to have something to collect
        attacker.initiate(depositAmount, unlockTime);
        // Warp past unlock time
        vm.warp(block.timestamp + unlockTime + 1);
        // Now trigger reentrancy via Collect -> fallback -> Put
        uint256 contractBalanceBefore = address(c).balance;
        attacker.launchAttack(depositAmount);
        // After all calls, sum of all balances should never exceed contract's ETH balance
        uint256 totalAccBalance = c.Acc(address(attacker)).balance;
        assertTrue(totalAccBalance <= address(c).balance);
    }
}

contract ReenteringAttacker {
    C target;
    uint256 amountToReenter;
    bool attacking;

    constructor(C _target) {
        target = _target;
        attacking = false;
    }

    function initiate(uint256 amount, uint256 unlockTime) external payable {
        target.Put{value: msg.value}(unlockTime);
    }

    function launchAttack(uint256 amount) external {
        attacking = true;
        amountToReenter = amount;
        target.Collect(amount);
        attacking = false;
    }

    fallback() external payable {
        if (attacking) {
            attacking = false;
            target.Put{value: msg.value}(0);
        }
    }
}

