pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 collectAmount, uint256 timestamp) public {
        // Make the caller the test contract itself
        address actor = address(this);
        uint256 putAmount = 2 ether;
        uint256 minSum = 1 ether;
        // Bound the collectAmount to be at most putAmount and at least minSum to make success plausible
        vm.assume(collectAmount >= minSum && collectAmount <= putAmount);
        // Set a future unlock timestamp
        uint256 unlockTime = block.timestamp + 1 days;
        // Warp to a timestamp before unlockTime
        vm.warp(timestamp);
        vm.assume(timestamp < unlockTime);

        // Fund actor
        vm.deal(actor, putAmount);
        vm.prank(actor);
        c.Put{value: putAmount}(unlockTime);

        // Attempt Collect before unlock time
        bool ok = false;
        vm.prank(actor);
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The property: Collect should fail (ok == false) when timestamp <= unlockTime
        // Because we warped before unlockTime, the correct contract must revert; the mutant succeeds.
        assertTrue(!ok);
    }
}

