pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        // bound to admissible domain: positive amount within reasonable range, unlockTime compared to block.timestamp
        bound(amount, 1, 10000 ether);
        bound(unlockTime, block.timestamp, block.timestamp + 365 days);
        address depositor = address(0x1234);
        address collector = address(0x5678);
        // depositor puts funds with future unlockTime
        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.Put{value: amount}(unlockTime);
        // collector attempts to Collect before unlock (block.timestamp unchanged, still < unlockTime if unlockTime > current)
        vm.deal(collector, 0);
        vm.prank(collector);
        bool ok;
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // invariant: if Collect succeeded, 
        // the collector's balance must have been reduced by amount and contract's Ether reduced by amount.
        // But the mutant allows Collect without unlock, and the external call will revert (because collector has no fallback),
        // so the subtraction is skipped, leading to acc.balance unchanged while contract Ether may be lost if call didn't revert? 
        // Actually, mutant execution: call to collector EOA succeeds (returns true), 
        // so acc.balance -= amount happens, and contract Ether is lost. Correct unlock rejects.
        // The true invariant: after a successful Collect call, the contract's Ether balance must have decreased by amount.
        uint256 contractBalBefore = address(c).balance;
        // re-do the operation after reset? Better: measure directly.
        // Let's compute: after setup, c.balance == amount. If Collect succeeds, c.balance becomes 0.
        // In mutant, Collect succeeds before unlock, so c.balance becomes 0 as well.
        // That doesn't differentiate. Need a different rule.
        // Correct rule: a Collect call before unlockTime MUST revert.
        // We set unlockTime > block.timestamp, so correct contract reverts, mutant does not.
        // So assert: ok == false (revert expectation). This is a general rule for unlockTime > block.timestamp.
        // But the fuzzer may generate unlockTime == block.timestamp, then both succeed.
        // We need to restrict to only those inputs where unlockTime > block.timestamp. 
        vm.assume(unlockTime > block.timestamp);
        // Now correct MUST revert, mutant succeeds.
        // Wait, we already set up the state once; we need to ensure we read state before/after correctly.
        // Actually we used depositor to Put, then collector calls Collect. The contract's logic for Collect uses msg.sender (collector)
        // which has no balance. So acc.balance = 0 for collector, so condition fails, both will not even enter if block.
        // We need to make collector the same as depositor.
        // So let's fix: use a single actor.
        address actor = address(0x1234);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        // Now warping? No, we want to test before unlock. block.timestamp is still less than unlockTime (assume).
        // actor calls Collect
        vm.prank(actor);
        try c.Collect(amount) returns (bool _) {
            ok = true;
        } catch {
            ok = false;
        }
        // assertion: ok must be false (revert) for correct contract, but mutant should succeed.
        // However, if the call to actor succeeds (since actor is EOA), Collect mutates state.
        // In the correct contract, the entire Collect call reverts because modifier nonReentrant_ passes, 
        // but inside the if condition, block.timestamp > acc.unlockTime fails, so nothing happens, returns normally, no revert.
        // Wait, the original Collect function: if condition fails, it just returns, not reverts.
        // So correct contract does NOT revert; it simply does nothing. The state remains unchanged.
        // The mutant removes the unlockTime check, so condition true, then call to actor sends Ether, then subtracts balance.
        // So after the call, the actor's balance in Acc mapping decreases, and contract's Ether decreases.
        // The correct behavior: state unchanged. So we can assert that after the call, the actor's balance remains the original amount.
        // But we need an assertion that holds for reference and fails for mutant.
        // Let's assert: c.Acc(actor).balance == amount (unchanged). Reference: true. Mutant: false because balance deducted.
        // This is perfect.
        assertEq(c.Acc(actor).balance, amount);
    }
}

