pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter reverter;

    function setUp() public {
        reverter = new Reverter();
        c = new C(address(this));
    }

    function testFuzz_property(uint256 amount, uint256 putAmount, uint256 unlockTime, bool warped) public {
        vm.assume(amount > 0);
        vm.assume(putAmount >= amount);
        vm.assume(putAmount >= 1 ether);
        vm.assume(unlockTime > block.timestamp);
        vm.assume(amount <= 1 ether);

        address collector = address(reverter);
        vm.deal(collector, putAmount);
        vm.prank(collector);
        c.Put{value: putAmount}(unlockTime);

        uint256 balanceBefore = c.Acc(collector).balance;
        if (warped) {
            vm.warp(unlockTime + 1);
        }

        vm.prank(collector);
        try c.Collect(amount) returns (bool success) {
            uint256 balanceAfter = c.Acc(collector).balance;
            assertTrue(balanceBefore - balanceAfter == amount);
        } catch {
            assertTrue(true);
        }
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

