pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 putAmount, uint256 collectAmount, address other) public {
        // Bound amounts to avoid overflow and ensure MinSum is met for collection
        putAmount = bound(putAmount, 1 ether, 100 ether);
        collectAmount = bound(collectAmount, 1 ether, putAmount);
        vm.assume(collectAmount <= putAmount);
        // other must be different from this contract to avoid LogFile interference
        vm.assume(other != address(this));

        // Give the actor some Ether and have them Put it into the contract with no unlock time (0)
        vm.deal(other, putAmount);
        vm.prank(other);
        c.Put{value: putAmount}(0);

        // Record balances before collection attempt
        uint256 balBefore = address(c).balance;
        uint256 otherBalBefore = other.balance;
        uint256 accBalBefore = c.Acc(other).balance;
        uint256 unlockTime = c.Acc(other).unlockTime;

        // Attempt a Collect that is premature because unlockTime is 0 but block.timestamp > 0
        vm.prank(other);
        bool ok = true;
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balAfter = address(c).balance;
        uint256 otherBalAfter = other.balance;
        uint256 accBalAfter = c.Acc(other).balance;

        // The invariant: if Collect did not revert, the collector's balance must have decreased by collectAmount.
        // The reference contract reverts because block.timestamp > unlockTime is false (unlockTime == 0),
        // so the invariant holds trivially. The mutant succeeds but fails to decrement the balance
        // (external call reverts, subtraction skipped), thus violating the invariant.
        assertTrue(!ok || (accBalBefore - accBalAfter) == collectAmount, "Collect succeeded but balance not correctly reduced");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

