pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 putAmount, uint256 collectAmount, uint256 unlockTime, bool warpPast) public {
        // 1. Bound amounts to admissible range (>= 1 ether so they meet MinSum when needed, and <= address max balance)
        uint256 min = 1 ether;
        putAmount = bound(putAmount, min, type(uint128).max);
        collectAmount = bound(collectAmount, min, type(uint128).max);
        unlockTime = bound(unlockTime, block.timestamp + 1, type(uint64).max);

        // 2. Deploy a helper that always reverts on receive to ensure the external call in Collect reverts
        Reverter reverter = new Reverter();
        address actor = address(reverter);

        // Fund the actor and make it put Ether into C with a future unlock time
        vm.deal(actor, putAmount);
        vm.prank(actor);
        c.Put{value: putAmount}(unlockTime);

        // Manipulate time if needed to test both past and future unlockTime
        if (!warpPast) {
            vm.warp(unlockTime + 1);
        } // else leave block.timestamp < unlockTime

        // Record actor's balance before Collect
        uint256 balBefore = c.Acc(actor).balance;

        // Ensure actor has enough balance to attempt the collect
        vm.assume(collectAmount <= balBefore);

        // Fund actor with some ETH for the fallback revert to work (it will not receive anything)
        vm.deal(actor, 1 ether);

        // Make the Collect call and capture success
        bool success;
        vm.prank(actor);
        try c.Collect(collectAmount) {
            success = true;
        } catch {
            success = false;
        }

        // The invariant: if Collect succeeded, the actor's balance must have decreased
        assertTrue(!success || c.Acc(actor).balance < balBefore);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

