pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint240 amount, address actor) public {
        uint256 am = uint256(amount);
        vm.assume(am >= 1 ether);
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        // Provide funding and put Ether
        vm.deal(actor, am + 1 ether);
        vm.prank(actor);
        c{value: am}();
        // Warp past unlock time
        vm.warp(block.timestamp + 1 days);
        // Record balance before Collect
