        // Collect fails with insufficient MinSum or insufficient balance, but we ensure both are satisfied
        vm.assume(balBefore >= am);
        vm.prank(actor);
        c.Collect(am);
        // Post-Collect balance
        uint256 balAfter = c.Acc(actor).balance;
        // Correct invariant: balAfter <= balBefore - am  (i.e., sub_uint256 ensures reduction)
        // Bug adds instead, giving balAfter == balBefore + am > balBefore - am
        assertTrue(balAfter <= balBefore - am);
    }
}
